// LoadMatchPlayer loads the matchPlayerSession's MatchPlayer into the .R struct
func (o *MatchPlayerSession) LoadMatchPlayer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.MatchPlayer = nil
	o.R.Loaded.MatchPlayer = false

	related, err := o.MatchPlayer(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.MatchPlayerSessions = MatchPlayerSessionSlice{o}

	o.R.MatchPlayer = related
	o.R.Loaded.MatchPlayer = true
	return nil
}

// LoadMatchPlayer loads the matchPlayerSession's MatchPlayer into the .R struct
func (os MatchPlayerSessionSlice) LoadMatchPlayer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	matchPlayers, err := os.MatchPlayer(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.MatchPlayer = nil
		o.R.Loaded.MatchPlayer = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	matchPlayerSessionByKey := make(map[int64][]*MatchPlayerSession, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		matchPlayerSessionByKey[o.MatchPlayerID] = append(matchPlayerSessionByKey[o.MatchPlayerID], o)
	}

	for _, rel := range matchPlayers {

		owners, ok := matchPlayerSessionByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.MatchPlayer != nil {
				continue
			}

			rel.R.MatchPlayerSessions = append(rel.R.MatchPlayerSessions, o)

			o.R.MatchPlayer = rel

		}
	}

	return nil
}

type matchPlayerSessionJoins[Q dialect.Joinable] struct {
	typ         string
	MatchPlayer modAs[Q, matchPlayerColumns]
}

func (j matchPlayerSessionJoins[Q]) aliasedAs(alias string) matchPlayerSessionJoins[Q] {
	return buildMatchPlayerSessionJoins[Q](buildMatchPlayerSessionColumns(alias), j.typ)
}

func buildMatchPlayerSessionJoins[Q dialect.Joinable](cols matchPlayerSessionColumns, typ string) matchPlayerSessionJoins[Q] {
	return matchPlayerSessionJoins[Q]{
		typ: typ,
		MatchPlayer: modAs[Q, matchPlayerColumns]{
			c: MatchPlayers.Columns,
			f: func(to matchPlayerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, MatchPlayers.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.MatchPlayerID),
					))
				}

				return mods
			},
		},
	}
}
